import { prisma } from '@cms/database'

// ISO 3166-1 alpha-2. Names are generated by the runtime's CLDR data so we do
// not have to keep a second, error-prone country-name directory in the CMS.
const CODES = `AF AX AL DZ AS AD AO AI AQ AG AR AM AW AU AT AZ BS BH BD BB BY BE BZ BJ BM BT BO BQ BA BW BV BR IO BN BG BF BI CV KH CM CA KY CF TD CL CN CX CC CO KM CG CD CK CR CI HR CU CW CY CZ DK DJ DM DO EC EG SV GQ ER EE SZ ET FK FO FJ FI FR GF PF TF GA GM GE DE GH GI GR GL GD GP GU GT GG GN GW GY HT HM VA HN HK HU IS IN ID IR IQ IE IM IL IT JM JP JE JO KZ KE KI KP KR KW KG LA LV LB LS LR LY LI LT LU MO MG MW MY MV ML MT MH MQ MR MU YT MX FM MD MC MN ME MS MA MZ MM NA NR NP NL NC NZ NI NE NG NU NF MK MP NO OM PK PW PS PA PG PY PE PH PN PL PT PR QA RE RO RU RW BL SH KN LC MF PM VC WS SM ST SA SN RS SC SL SG SX SK SI SB SO ZA GS SS ES LK SD SR SJ SE CH SY TW TJ TZ TH TL TG TK TO TT TN TR TM TC TV UG UA AE GB US UM UY UZ VU VE VN VG VI WF EH YE ZM ZW`.split(' ')
const english = new Intl.DisplayNames(['en'], { type: 'region' })
const chinese = new Intl.DisplayNames(['zh-CN'], { type: 'region' })

export const isIsoCountryCode = (value: unknown): value is string => typeof value === 'string' && CODES.includes(value.toUpperCase())
export const normalizeCountryCode = (value: unknown) => {
  const code = String(value || 'MY').trim().toUpperCase()
  if (!isIsoCountryCode(code)) throw new Error('Country must be a valid ISO 3166-1 alpha-2 code')
  return code
}

type StoredCountry = { code: string; retrievalEnabled: boolean; displayEnabled: boolean; isDefault: boolean }
export function presentCountry(code: string, value?: StoredCountry, sourceCount = 0) {
  // Countries are opt-in. Malaysia is the seeded/default reader country and
  // remains enabled so existing sources and published content stay available.
  return { code, name: english.of(code) || code, nameZh: chinese.of(code) || code, retrievalEnabled: value?.retrievalEnabled ?? code === 'MY', displayEnabled: value?.displayEnabled ?? code === 'MY', isDefault: value?.isDefault ?? code === 'MY', sourceCount }
}

export async function listCountries() {
  const [settings, grouped] = await Promise.all([
    prisma.newsBotCountry.findMany(),
    prisma.newsBotSource.groupBy({ by: ['countryCode'], _count: { _all: true } })
  ])
  const byCode = new Map(settings.map(setting => [setting.code, setting]))
  const counts = new Map(grouped.map(group => [group.countryCode, group._count._all]))
  return CODES.map(code => presentCountry(code, byCode.get(code), counts.get(code) || 0))
}

export async function countrySettings(codes: string[]) {
  const rows = await prisma.newsBotCountry.findMany({ where: { code: { in: [...new Set(codes)] } } })
  return new Map(rows.map(row => [row.code, row]))
}

export async function publicCountryConfiguration() {
  const all = await listCountries()
  const countries = all.filter(country => country.displayEnabled)
  const selectedDefault = countries.find(country => country.isDefault) || countries.find(country => country.code === 'MY') || countries[0]
  return { countries: countries.map(({ code, name, nameZh }) => ({ code, name, nameZh })), defaultCountryCode: selectedDefault?.code || 'MY' }
}
